@contextmanager
def patch_object(obj, name, side_effect):
    original = getattr(obj, name)
    def replacement(*args, **kwargs):
        raise side_effect
    setattr(obj, name, replacement)
    try:
        yield
    finally:
        setattr(obj, name, original)

